 import type { Options } from './../options';

 function noRefCheck() {}

 const singleReturnFunction = /^function(\s*[^(]*)\(([^)]*)\) \{\n\s+return ([^\n]+);\n\s+\}$/;

 const normalizeFunctionString = (value: string): string =>
   value.replace(
     singleReturnFunction,
     (match, name, args, returnValue) => {
       if (name.trim() && !args) {
         return match;
       }

       return `function${name}(${args}) {return ${returnValue};}`;
     }
   );

 const defaultFunctionValue = (fn: any): any =>
   normalizeFunctionString(fn.toString());

 export default (fn: Function, options: Options): string => {
   const { functionValue = defaultFunctionValue, showFunctions } = options;
   if (!showFunctions && functionValue === defaultFunctionValue) {
     return functionValue(noRefCheck);
   }

   return functionValue(fn);
 };

